scene.background = new THREE.Color('#10141f');
camera.position.set(4, 3, 6);
controls.target.set(0, 0, 0);

// A soft studio light and a directional key light.
scene.add(new THREE.HemisphereLight('#cbdcff', '#45415d', 2));
const light = new THREE.DirectionalLight('#ffffff', 3);
light.position.set(3, 5, 4);
scene.add(light);

const grid = new THREE.GridHelper(14, 28, '#30374d', '#202738');
grid.position.y = -1.05;
scene.add(grid);

const geometry = new THREE.SphereGeometry(1, 32, 24);
const material = new THREE.MeshStandardMaterial({
  color: '#b49aff', roughness: 0.4, metalness: 0.15
});
const mesh = new THREE.Mesh(geometry, material);
scene.add(mesh);

// Generate a tiny image locally: no downloaded assets needed.
const image = document.createElement('canvas');
image.width = image.height = 128;
const ctx = image.getContext('2d');
ctx.fillStyle = '#b49aff';
ctx.fillRect(0, 0, 128, 128);
ctx.fillStyle = '#30344b';
ctx.fillRect(0, 0, 64, 64);
ctx.fillRect(64, 64, 64, 64);
const texture = new THREE.CanvasTexture(image);
texture.colorSpace = THREE.SRGBColorSpace;
material.map = null;
material.color.set('#ffffff');
material.needsUpdate = true;

